 1	import { CliExit, getProgramName, parseTest17Args } from './lib/cli/test17Args.mjs';
 2	import { pythonRepr } from './lib/format/pythonRepr.mjs';
 3	import { decodeJwt, encodeJwt } from './lib/jwt/hs256.mjs';
 4	
 5	const SECRET = 'secret';
 6	
 7	export function main(argv = process.argv.slice(2), scriptPath = process.argv[1]) {
 8	  const programName = getProgramName(scriptPath);
 9	  const args = parseTest17Args(argv, programName);
10	
11	  const payload = {
12	    info: args.data,
13	    iat: Math.floor(Date.now() / 1000),
14	  };
15	  const token = encodeJwt(payload, SECRET);
16	  process.stdout.write(`${token}\n`);
17	
18	  const verifyIat = args.verify_iat === 'true';
19	  const decoded = decodeJwt(token, SECRET, { verify_iat: verifyIat }, ['HS256']);
20	  process.stdout.write(`${pythonRepr(decoded)}\n`);
21	}
22	
23	function handleCliExit(error) {
24	  const stream = error.stream === 'stdout' ? process.stdout : process.stderr;
25	  stream.write(error.output);
26	  process.exitCode = error.status;
27	}
28	
29	try {
30	  main();
31	} catch (error) {
32	  if (error instanceof CliExit) {
33	    handleCliExit(error);
34	  } else {
35	    throw error;
36	  }
37	}

  1	export class CliExit extends Error {
  2	  constructor(status, output, stream) {
  3	    super(output);
  4	    this.name = 'CliExit';
  5	    this.status = status;
  6	    this.output = output;
  7	    this.stream = stream;
  8	  }
  9	}
 10	
 11	function getUsage(programName) {
 12	  return `usage: ${programName} [-h] --data DATA --verify_iat {true,false}`;
 13	}
 14	
 15	function getHelpText(programName) {
 16	  return `${getUsage(programName)}\n\noptions:\n  -h, --help            show this help message and exit\n  --data DATA\n  --verify_iat {true,false}\n`;
 17	}
 18	
 19	function createParserError(programName, message) {
 20	  return new CliExit(2, `${getUsage(programName)}\n${programName}: error: ${message}\n`, 'stderr');
 21	}
 22	
 23	function isNegativeNumberLike(value) {
 24	  return /^-\d+$|^-\d*\.\d+$/u.test(value);
 25	}
 26	
 27	function readOptionValue(argv, index, optionName, programName) {
 28	  const token = argv[index];
 29	  const inlinePrefix = `${optionName}=`;
 30	
 31	  if (token.startsWith(inlinePrefix)) {
 32	    return { value: token.slice(inlinePrefix.length), nextIndex: index };
 33	  }
 34	
 35	  const nextValue = argv[index + 1];
 36	  if (
 37	    nextValue === undefined ||
 38	    (nextValue.startsWith('-') && !isNegativeNumberLike(nextValue))
 39	  ) {
 40	    throw createParserError(programName, `argument ${optionName}: expected one argument`);
 41	  }
 42	
 43	  return { value: nextValue, nextIndex: index + 1 };
 44	}
 45	
 46	export function getProgramName(scriptPath) {
 47	  const normalizedPath = String(scriptPath ?? '');
 48	  const pathParts = normalizedPath.split(/[/\\]/u);
 49	  return pathParts[pathParts.length - 1] || 'test17.mjs';
 50	}
 51	
 52	export function parseTest17Args(argv, programName) {
 53	  const values = {
 54	    data: undefined,
 55	    verify_iat: undefined,
 56	  };
 57	  const extras = [];
 58	
 59	  for (let index = 0; index < argv.length; index += 1) {
 60	    const token = argv[index];
 61	
 62	    if (token === '-h' || token === '--help') {
 63	      throw new CliExit(0, getHelpText(programName), 'stdout');
 64	    }
 65	
 66	    if (token === '--') {
 67	      extras.push(...argv.slice(index + 1));
 68	      break;
 69	    }
 70	
 71	    if (token === '--data' || token.startsWith('--data=')) {
 72	      const parsed = readOptionValue(argv, index, '--data', programName);
 73	      values.data = parsed.value;
 74	      index = parsed.nextIndex;
 75	      continue;
 76	    }
 77	
 78	    if (token === '--verify_iat' || token.startsWith('--verify_iat=')) {
 79	      const parsed = readOptionValue(argv, index, '--verify_iat', programName);
 80	      if (parsed.value !== 'true' && parsed.value !== 'false') {
 81	        throw createParserError(
 82	          programName,
 83	          `argument --verify_iat: invalid choice: '${parsed.value}' (choose from 'true', 'false')`,
 84	        );
 85	      }
 86	
 87	      values.verify_iat = parsed.value;
 88	      index = parsed.nextIndex;
 89	      continue;
 90	    }
 91	
 92	    extras.push(token);
 93	  }
 94	
 95	  const missing = [];
 96	  if (values.data === undefined) {
 97	    missing.push('--data');
 98	  }
 99	  if (values.verify_iat === undefined) {
100	    missing.push('--verify_iat');
101	  }
102	  if (missing.length > 0) {
103	    throw createParserError(programName, `the following arguments are required: ${missing.join(', ')}`);
104	  }
105	  if (extras.length > 0) {
106	    throw createParserError(programName, `unrecognized arguments: ${extras.join(' ')}`);
107	  }
108	
109	  return values;
110	}

 1	function pythonStringRepr(value) {
 2	  let result = "'";
 3	
 4	  for (const character of value) {
 5	    if (character === '\\') {
 6	      result += '\\\\';
 7	      continue;
 8	    }
 9	    if (character === "'") {
10	      result += "\\'";
11	      continue;
12	    }
13	    if (character === '\n') {
14	      result += '\\n';
15	      continue;
16	    }
17	    if (character === '\r') {
18	      result += '\\r';
19	      continue;
20	    }
21	    if (character === '\t') {
22	      result += '\\t';
23	      continue;
24	    }
25	    if (character === '\b') {
26	      result += '\\b';
27	      continue;
28	    }
29	    if (character === '\f') {
30	      result += '\\f';
31	      continue;
32	    }
33	
34	    const codePoint = character.codePointAt(0);
35	    if (codePoint < 0x20 || codePoint === 0x7f) {
36	      result += `\\x${codePoint.toString(16).padStart(2, '0')}`;
37	      continue;
38	    }
39	
40	    result += character;
41	  }
42	
43	  return `${result}'`;
44	}
45	
46	export function pythonRepr(value) {
47	  if (typeof value === 'string') {
48	    return pythonStringRepr(value);
49	  }
50	  if (typeof value === 'number') {
51	    return Number.isFinite(value) ? String(value) : 'None';
52	  }
53	  if (typeof value === 'boolean') {
54	    return value ? 'True' : 'False';
55	  }
56	  if (value === null || value === undefined) {
57	    return 'None';
58	  }
59	  if (Array.isArray(value)) {
60	    return `[${value.map((item) => pythonRepr(item)).join(', ')}]`;
61	  }
62	  if (typeof value === 'object') {
63	    const entries = Object.entries(value).map(
64	      ([key, entryValue]) => `${pythonRepr(key)}: ${pythonRepr(entryValue)}`,
65	    );
66	    return `{${entries.join(', ')}}`;
67	  }
68	
69	  return pythonStringRepr(String(value));
70	}

 1	import { base64UrlDecode, base64UrlEncode, bytesToUtf8, utf8ToBytes } from '../encoding/base64url.mjs';
 2	import { hmacSha256 } from '../hash/hmacSha256.mjs';
 3	
 4	function normalizeSecret(secret) {
 5	  return typeof secret === 'string' ? utf8ToBytes(secret) : Uint8Array.from(secret);
 6	}
 7	
 8	function encodeSegment(value) {
 9	  return base64UrlEncode(utf8ToBytes(JSON.stringify(value)));
10	}
11	
12	function constantTimeEqual(left, right) {
13	  if (left.length !== right.length) {
14	    return false;
15	  }
16	
17	  let mismatch = 0;
18	  for (let index = 0; index < left.length; index += 1) {
19	    mismatch |= left.charCodeAt(index) ^ right.charCodeAt(index);
20	  }
21	  return mismatch === 0;
22	}
23	
24	function validateIssuedAt(payload) {
25	  if (!Object.prototype.hasOwnProperty.call(payload, 'iat')) {
26	    return;
27	  }
28	
29	  const issuedAt = payload.iat;
30	  if (typeof issuedAt === 'number' && Number.isInteger(issuedAt)) {
31	    return;
32	  }
33	  if (typeof issuedAt === 'string' && /^[+-]?\d+$/u.test(issuedAt.trim())) {
34	    return;
35	  }
36	
37	  throw new Error('Issued At claim (iat) must be an integer.');
38	}
39	
40	export function encodeJwt(payload, secret) {
41	  const header = { alg: 'HS256', typ: 'JWT' };
42	  const encodedHeader = encodeSegment(header);
43	  const encodedPayload = encodeSegment(payload);
44	  const signingInput = `${encodedHeader}.${encodedPayload}`;
45	  const signature = hmacSha256(normalizeSecret(secret), utf8ToBytes(signingInput));
46	  return `${signingInput}.${base64UrlEncode(signature)}`;
47	}
48	
49	export function decodeJwt(token, secret, options = {}, algorithms = ['HS256']) {
50	  const parts = token.split('.');
51	  if (parts.length !== 3) {
52	    throw new Error('Not enough segments');
53	  }
54	
55	  const [encodedHeader, encodedPayload, encodedSignature] = parts;
56	  const header = JSON.parse(bytesToUtf8(base64UrlDecode(encodedHeader)));
57	  if (!Array.isArray(algorithms) || !algorithms.includes(header.alg)) {
58	    throw new Error('The specified alg value is not allowed');
59	  }
60	  if (header.alg !== 'HS256') {
61	    throw new Error('Algorithm not supported');
62	  }
63	
64	  const signingInput = `${encodedHeader}.${encodedPayload}`;
65	  const expectedSignature = base64UrlEncode(
66	    hmacSha256(normalizeSecret(secret), utf8ToBytes(signingInput)),
67	  );
68	  if (!constantTimeEqual(encodedSignature, expectedSignature)) {
69	    throw new Error('Signature verification failed');
70	  }
71	
72	  const payload = JSON.parse(bytesToUtf8(base64UrlDecode(encodedPayload)));
73	  if (options.verify_iat !== false) {
74	    validateIssuedAt(payload);
75	  }
76	
77	  return payload;
78	}
